<script setup lang="ts">
import { PropType, ref, watch } from "vue";
import { Insert, NormalToolbar } from "md-editor-v3";
import { LoadingIcon, RocketIcon } from "tdesign-icons-vue-next";
import { PostProblemAIEnhancement } from "@/apis/problem.ts";

const props = defineProps({
  modelValue: {
    type: String as PropType<string>,
    default: "",
  },
  insert: {
    type: Function as PropType<Insert>,
    default: () => {
      //
    },
  },
});

const emit = defineEmits(["update:modelValue"]);

const drawerVisible = ref(false);
const previewContent = ref("");
const thinkingContent = ref("");
const isThinking = ref(false);
const abortController = ref<AbortController | null>(null);
const isLoading = ref(false);
const isGenerating = ref(false);
const errorMessage = ref("");
const inactivitySeconds = ref(0);
const thinkingCollapsed = ref(false);
const activeTab = ref("preview");
const copySuccess = ref(false);

// 不活动计时：与后端对齐，收到任何 AI 事件时重置
let inactivityTimer: ReturnType<typeof setInterval> | null = null;
const INACTIVITY_TIMEOUT = 35;

const startInactivityTimer = () => {
  inactivitySeconds.value = 0;
  inactivityTimer = setInterval(() => {
    inactivitySeconds.value++;
    if (inactivitySeconds.value >= INACTIVITY_TIMEOUT) {
      handleInactivityTimeout();
    }
  }, 1000);
};

const resetInactivityTimer = () => {
  inactivitySeconds.value = 0;
};

const stopInactivityTimer = () => {
  if (inactivityTimer) {
    clearInterval(inactivityTimer);
    inactivityTimer = null;
  }
};

const handleInactivityTimeout = () => {
  stopInactivityTimer();
  if (abortController.value) {
    abortController.value.abort();
    abortController.value = null;
  }
  isLoading.value = false;
  isThinking.value = false;
  isGenerating.value = false;
  errorMessage.value = "AI 服务响应超时，请稍后重试";
};

const handler = async () => {
  if (abortController.value) {
    abortController.value.abort();
    abortController.value = null;
  }

  previewContent.value = "";
  thinkingContent.value = "";
  isThinking.value = false;
  errorMessage.value = "";
  isLoading.value = true;
  isGenerating.value = true;
  drawerVisible.value = true;
  startInactivityTimer();

  abortController.value = new AbortController();

  try {
    await PostProblemAIEnhancement(
      props.modelValue,
      {
        onThinking: (chunk) => {
          isLoading.value = false;
          isThinking.value = true;
          resetInactivityTimer();
          thinkingContent.value += chunk;
        },
        onChunk: (chunk) => {
          isLoading.value = false;
          isThinking.value = false;
          resetInactivityTimer();
          previewContent.value += chunk;
        },
        onHeartbeat: () => {
          resetInactivityTimer();
        },
        onError: (message) => {
          isLoading.value = false;
          isThinking.value = false;
          isGenerating.value = false;
          stopInactivityTimer();
          errorMessage.value = message;
        },
        onDone: () => {
          isThinking.value = false;
          isGenerating.value = false;
          stopInactivityTimer();
        },
      },
      abortController.value.signal
    );
  } catch (e: any) {
    isLoading.value = false;
    isThinking.value = false;
    isGenerating.value = false;
    stopInactivityTimer();
    if (e.name !== "AbortError") {
      errorMessage.value = "请求失败，请稍后重试";
    }
  }

  isGenerating.value = false;
  stopInactivityTimer();
};

const handleConfirm = () => {
  emit("update:modelValue", "");
  props.insert((selectedText) => {
    return {
      targetValue: previewContent.value,
      select: false,
      deviationStart: 0,
      deviationEnd: 0,
    };
  });
  drawerVisible.value = false;
  previewContent.value = "";
  thinkingContent.value = "";
};

const handleStop = () => {
  if (abortController.value) {
    abortController.value.abort();
    abortController.value = null;
    isGenerating.value = false;
    isLoading.value = false;
    isThinking.value = false;
    stopInactivityTimer();
  }
};

const handleCancel = () => {
  drawerVisible.value = false;
  previewContent.value = "";
  thinkingContent.value = "";
};

const handleRetry = () => {
  errorMessage.value = "";
  handler();
};

const handleCopyRaw = async () => {
  try {
    await navigator.clipboard.writeText(previewContent.value);
    copySuccess.value = true;
    setTimeout(() => {
      copySuccess.value = false;
    }, 2000);
  } catch {
    // 降级方案：使用 textarea 复制
    const textarea = document.createElement("textarea");
    textarea.value = previewContent.value;
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand("copy");
    document.body.removeChild(textarea);
    copySuccess.value = true;
    setTimeout(() => {
      copySuccess.value = false;
    }, 2000);
  }
};

watch(drawerVisible, (newVal) => {
  if (!newVal && abortController.value) {
    abortController.value.abort();
    abortController.value = null;
  }
  if (!newVal) {
    stopInactivityTimer();
  }
});
</script>

<template>
  <NormalToolbar title="AI美化" @onClick="handler">
    <RocketIcon />
  </NormalToolbar>

  <t-drawer v-model:visible="drawerVisible" header="AI美化预览" size="large" :footer="true" :show-overlay="false"
    :size-draggable="true" :close-on-overlay-click="true">
    <div class="preview-container">
      <div v-if="errorMessage" class="error-container">
        <t-icon name="close-circle" size="32px" :style="{ color: 'var(--td-error-color)' }" />
        <p class="error-message">{{ errorMessage }}</p>
        <t-button theme="primary" variant="text" @click="handleRetry">重试</t-button>
      </div>
      <div v-else-if="isLoading" class="loading-container">
        <t-loading text="AI 正在连接中..." size="medium" />
        <p v-if="inactivitySeconds > 5" class="waiting-hint">已等待 {{ inactivitySeconds }} 秒</p>
      </div>
      <div v-else>
        <!-- 思考过程展示 -->
        <div v-if="thinkingContent" class="thinking-section">
          <div class="thinking-header" @click="thinkingCollapsed = !thinkingCollapsed">
            <t-icon name="chat" />
            <span>思考过程</span>
            <t-icon :name="thinkingCollapsed ? 'chevron-down' : 'chevron-up'" />
          </div>
          <div v-show="!thinkingCollapsed" class="thinking-body">
            <pre class="thinking-text">{{ thinkingContent }}</pre>
            <div v-if="isThinking" class="thinking-indicator">
              <t-loading size="small" />
              <span>思考中...</span>
            </div>
          </div>
        </div>
        <!-- 结果展示：有正式输出时显示 Tabs 切换，否则直接显示预览 -->
        <template v-if="previewContent">
          <t-tabs v-model="activeTab" class="result-tabs">
            <t-tab-panel value="preview" label="预览">
              <md-preview :model-value="previewContent" previewTheme="cyanosis" />
            </t-tab-panel>
            <t-tab-panel value="raw" label="原始文本">
              <div class="raw-text-container">
                <t-button size="small" variant="text" :theme="copySuccess ? 'success' : 'primary'" class="copy-btn" @click="handleCopyRaw">
                  {{ copySuccess ? '已复制' : '复制' }}
                </t-button>
                <pre class="raw-text">{{ previewContent }}</pre>
              </div>
            </t-tab-panel>
          </t-tabs>
        </template>
        <template v-else>
          <md-preview :model-value="previewContent" previewTheme="cyanosis" />
        </template>
        <div v-if="isGenerating" class="generating-hint">
          <t-loading size="small" />
          <span>AI 正在生成中...</span>
        </div>
      </div>
    </div>
    <template #footer>
      <t-space>
        <t-button theme="default" @click="handleCancel">取消</t-button>
        <t-button v-if="isGenerating" theme="danger" @click="handleStop">
          <template #icon>
            <LoadingIcon />
          </template>
          停止
        </t-button>
        <t-button v-else theme="primary" @click="handleConfirm" :disabled="!!errorMessage || !previewContent">替换
        </t-button>
      </t-space>
    </template>
  </t-drawer>
</template>

<style scoped>
.preview-container {
  max-height: calc(100vh - 200px);
  overflow-y: auto;
}

.loading-container {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 200px;
  gap: 12px;
}

.waiting-hint {
  color: var(--td-text-color-secondary);
  font-size: 13px;
  margin: 0;
}

.error-container {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 200px;
  gap: 12px;
}

.error-message {
  color: var(--td-error-color);
  font-size: 14px;
  margin: 0;
}

.thinking-section {
  margin-bottom: 16px;
  border: 1px solid var(--td-component-border);
  border-radius: var(--td-radius-default);
  overflow: hidden;
}

.thinking-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  background-color: var(--td-bg-color-secondarycontainer);
  cursor: pointer;
  font-size: 13px;
  color: var(--td-text-color-secondary);
  user-select: none;
}

.thinking-header span {
  flex: 1;
}

.thinking-body {
  padding: 12px;
  background-color: var(--td-bg-color-container-hover);
}

.thinking-text {
  white-space: pre-wrap;
  word-wrap: break-word;
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--td-text-color-secondary);
  font-family: inherit;
}

.thinking-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  color: var(--td-text-color-placeholder);
  font-size: 12px;
}

.generating-hint {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 0;
  color: var(--td-text-color-secondary);
  font-size: 13px;
}

.raw-text-container {
  position: relative;
}

.copy-btn {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 1;
}

.raw-text {
  white-space: pre-wrap;
  word-wrap: break-word;
  margin: 0;
  padding: 12px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--td-text-color-primary);
  font-family: var(--td-font-family-mono);
  background-color: var(--td-bg-color-secondarycontainer);
  border-radius: var(--td-radius-default);
  max-height: calc(100vh - 400px);
  overflow-y: auto;
}
</style>
